<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Roman Numeral Converter Online','description'=>'Convert numbers to Roman numerals and Roman numerals to numbers.','url'=>'https://smarttoolz.in/tools/roman-numeral-converter/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">ROMAN NUMERALS</span><h1>Roman Numeral Converter</h1><p>Convert between standard numbers and Roman numerals.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Input<input id="in" placeholder="2026 or MMXXVI"></label><button id="go" class="tool-btn">Convert</button><p id="out" style="font-size:24px;font-weight:800"></p></div></section></main><script>(()=>{const $=id=>document.getElementById(id),map=[[1000,'M'],[900,'CM'],[500,'D'],[400,'CD'],[100,'C'],[90,'XC'],[50,'L'],[40,'XL'],[10,'X'],[9,'IX'],[5,'V'],[4,'IV'],[1,'I']];function toR(n){let s='';for(const [v,c] of map){while(n>=v){s+=c;n-=v}}return s}function fromR(s){let n=0;for(let i=0;i<s.length;i++){let a=map.find(x=>x[1]===s[i])?.[0]||0,b=map.find(x=>x[1]===s[i+1])?.[0]||0;n+=a<b?-a:a}return n}$( 'go').onclick=()=>{let s=$('in').value.trim().toUpperCase();if(/^\d+$/.test(s)){let n=+s;$('out').textContent=n>=1&&n<=3999?toR(n):'Enter a number from 1 to 3999.'}else if(/^[IVXLCDM]+$/.test(s))$('out').textContent=fromR(s);else $('out').textContent='Enter a valid number or Roman numeral.'}})();</script><?php smarttoolz_tool_page_end(); ?>